head.script:
scwin.onpageload = function () {
    var top = $p.top();
    if (!top || !top.scwin || typeof top.scwin.log !== "function") {
        return;
    }
    top.scwin.log("[includeFrame 자식] printFormInfo_WAEA-1063_(WSQ-6421)_inc.xml onpageload");
    // includeFrame 은 부모와 scope($p)를 공유하므로 자식 화면에서 $p 로 호출하면 부모 규격이 나온다.
    top.scwin.log("  자식 화면에서 $p.getPrintFormInfo().type = " + $p.getPrintFormInfo("type") + " (부모 것이 나오는 것이 정상)");
};
